using System.Security.Claims;using System.Text;using System.Text.Json;using DadoHome.Api.Auth;using DadoHome.Api.Data;using DadoHome.Api.Payments;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddDbContext<DadoDbContext>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("DadoDb")));builder.Services.AddSingleton<OtpService>();builder.Services.AddSingleton<JwtService>();builder.Services.AddSingleton<PasswordService>();builder.Services.AddScoped<PaymentService>();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();var key=Encoding.UTF8.GetBytes(builder.Configuration["Jwt:Key"]??throw new InvalidOperationException("Jwt:Key missing"));builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidAudience=builder.Configuration["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(key)});builder.Services.AddAuthorization();var app=builder.Build();app.UseSwagger();app.UseSwaggerUI();app.UseHttpsRedirection();app.UseAuthentication();app.UseAuthorization();Guid? U(ClaimsPrincipal u)=>Guid.TryParse(u.FindFirstValue(ClaimTypes.NameIdentifier)??u.FindFirstValue("sub"),out var id)?id:null;
app.MapGet("/health",()=>Results.Ok(new{service="DadoHome.Api",status="ok"}));app.MapPost("/api/auth/otp/request",(OtpRequest r,OtpService otp,IHostEnvironment env)=>{if(string.IsNullOrWhiteSpace(r.Phone))return Results.BadRequest();var code=otp.Issue(r.Phone);return Results.Ok(env.IsDevelopment()?new{sent=true,devCode=code}:new{sent=true});});app.MapPost("/api/auth/otp/verify",async(OtpVerify r,OtpService otp,JwtService jwt,DadoDbContext db)=>{if(!otp.Verify(r.Phone,r.Code))return Results.Unauthorized();var user=await db.Customers.FirstOrDefaultAsync(x=>x.Phone==r.Phone);if(user is null){user=new Customer{Id=Guid.NewGuid(),Phone=r.Phone};db.Customers.Add(user);db.Wallets.Add(new Wallet{Id=Guid.NewGuid(),CustomerId=user.Id});await db.SaveChangesAsync();}return Results.Ok(new{accessToken=jwt.Create(user.Id,user.Phone,Roles.Customer),expiresIn=1800});});app.MapPost("/api/admin/auth/login",async(StaffLoginRequest r,DadoDbContext db,PasswordService passwords,JwtService jwt)=>{var s=await db.StaffUsers.SingleOrDefaultAsync(x=>x.Phone==r.Phone&&x.IsActive);if(s is null||!passwords.Verify(r.Password,s.PasswordHash))return Results.Unauthorized();return Results.Ok(new{accessToken=jwt.Create(s.Id,s.Phone,s.Role),expiresIn=1800,user=new{s.Id,s.Name,s.Phone,s.Role}});});
app.MapGet("/api/products",async(DadoDbContext db)=>await db.Products.Where(x=>x.IsActive).ToListAsync());app.MapGet("/api/admin/products",async(DadoDbContext db)=>await db.Products.OrderByDescending(x=>x.CreatedAt).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator));app.MapPost("/api/admin/products",async(ProductWrite r,DadoDbContext db)=>{if(string.IsNullOrWhiteSpace(r.Name)||r.Price<0||r.Stock<0)return Results.BadRequest();var p=new Product{Id=Guid.NewGuid(),Name=r.Name.Trim(),Category=r.Category,Description=r.Description,ImageUrl=r.ImageUrl,Sizes=r.Sizes,Colors=r.Colors,Price=r.Price,Stock=r.Stock,IsActive=r.IsActive};db.Products.Add(p);await db.SaveChangesAsync();return Results.Created($"/api/admin/products/{p.Id}",p);}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator));app.MapPut("/api/admin/products/{id:guid}",async(Guid id,ProductWrite r,DadoDbContext db)=>{var p=await db.Products.FindAsync(id);if(p is null)return Results.NotFound();if(string.IsNullOrWhiteSpace(r.Name)||r.Price<0||r.Stock<0)return Results.BadRequest();p.Name=r.Name.Trim();p.Category=r.Category;p.Description=r.Description;p.ImageUrl=r.ImageUrl;p.Sizes=r.Sizes;p.Colors=r.Colors;p.Price=r.Price;p.Stock=r.Stock;p.IsActive=r.IsActive;await db.SaveChangesAsync();return Results.Ok(p);}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator));app.MapDelete("/api/admin/products/{id:guid}",async(Guid id,DadoDbContext db)=>{var p=await db.Products.FindAsync(id);if(p is null)return Results.NotFound();p.IsActive=false;await db.SaveChangesAsync();return Results.NoContent();}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator));
app.MapPost("/api/orders",async(CreateOrderRequest r,ClaimsPrincipal user,DadoDbContext db)=>{var id=U(user);if(id is null)return Results.Unauthorized();var order=new Order{Id=Guid.NewGuid(),CustomerId=id.Value,Number=$"DH-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000,9999)}",Status="Created",DeliveryMethod=r.DeliveryMethod,PaymentMethod=r.PaymentMethod,Total=r.Items.Sum(x=>x.UnitPrice*x.Quantity)};db.Orders.Add(order);foreach(var x in r.Items)db.OrderItems.Add(new OrderItem{Id=Guid.NewGuid(),OrderId=order.Id,ProductId=x.ProductId,ProductName=x.ProductName,Variant=x.Variant,Quantity=x.Quantity,UnitPrice=x.UnitPrice});await db.SaveChangesAsync();return Results.Created($"/api/orders/{order.Id}",order);}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapGet("/api/me/orders",async(ClaimsPrincipal user,DadoDbContext db)=>{var id=U(user);return id is null?Results.Unauthorized():Results.Ok(await db.Orders.Where(x=>x.CustomerId==id).OrderByDescending(x=>x.CreatedAt).ToListAsync());}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));
app.MapGet("/api/wallet",async(ClaimsPrincipal user,DadoDbContext db,PaymentService ps)=>{var id=U(user);if(id is null)return Results.Unauthorized();var w=await db.Wallets.SingleAsync(x=>x.CustomerId==id);return Results.Ok(new{id=w.Id,currency=w.Currency,balance=await ps.WalletBalance(id.Value),transactions=await db.WalletEntries.Where(x=>x.WalletId==w.Id).OrderByDescending(x=>x.CreatedAt).Take(50).ToListAsync()});}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapPost("/api/payments/intents",async(PaymentIntentRequest r,ClaimsPrincipal user,PaymentService ps)=>{var id=U(user);return id is null?Results.Unauthorized():Results.Ok(await ps.CreateIntent(id.Value,r));}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapPost("/api/wallet/pay",async(WalletPayRequest r,ClaimsPrincipal user,DadoDbContext db,PaymentService ps)=>{var id=U(user);if(id is null)return Results.Unauthorized();var order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==r.OrderId&&x.CustomerId==id);if(order is null)return Results.NotFound();if(await ps.WalletBalance(id.Value)<order.Total)return Results.BadRequest(new{error="InsufficientBalance"});var w=await db.Wallets.SingleAsync(x=>x.CustomerId==id);db.WalletEntries.Add(new WalletEntry{Id=Guid.NewGuid(),WalletId=w.Id,OrderId=order.Id,Amount=-order.Total,Type="OrderPayment",Status="Successful",ExternalId=$"order:{order.Id}"});order.Status="Paid";await db.SaveChangesAsync();return Results.Ok(new{paid=true,order.Id,order.Total});}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapPost("/api/payments/webhook",async(HttpRequest req,PaymentService ps)=>{using var sr=new StreamReader(req.Body);var body=await sr.ReadToEndAsync();var sig=req.Headers["X-Dado-Signature"].ToString();if(string.IsNullOrWhiteSpace(sig)||!ps.VerifyWebhook(body,sig))return Results.Unauthorized();var e=JsonSerializer.Deserialize<PaymentWebhook>(body,new JsonSerializerOptions{PropertyNameCaseInsensitive=true});return e is null?Results.BadRequest():await ps.ApplyWebhook(e)?Results.Ok():Results.NotFound();});
app.MapGet("/api/admin/dashboard",async(DadoDbContext db)=>{var today=DateTime.UtcNow.Date;var orders=await db.Orders.Where(x=>x.CreatedAt>=today).ToListAsync();return Results.Ok(new{salesToday=orders.Where(x=>x.Status=="Paid").Sum(x=>x.Total),ordersToday=orders.Count,averageCheck=orders.Count==0?0:orders.Average(x=>x.Total),newCustomers=await db.Customers.CountAsync(x=>x.CreatedAt>=today)});}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager,Roles.Finance,Roles.Support));app.MapGet("/api/admin/payments",async(DadoDbContext db)=>await db.Payments.OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.Finance,Roles.Support));app.MapGet("/api/admin/refunds",async(DadoDbContext db)=>await db.Refunds.OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.Finance,Roles.Support));app.MapGet("/api/admin/wallet-entries",async(DadoDbContext db)=>await db.WalletEntries.OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.Finance,Roles.Support));app.MapPost("/api/admin/refunds",async(RefundRequest r,ClaimsPrincipal user,DadoDbContext db)=>{var payment=await db.Payments.FindAsync(r.PaymentId);if(payment is null||r.Amount<=0||r.Amount>payment.Amount)return Results.BadRequest();var refund=new Refund{Id=Guid.NewGuid(),PaymentId=payment.Id,Amount=r.Amount,Reason=r.Reason,Status="Pending"};db.Refunds.Add(refund);db.AuditLogs.Add(new AuditLog{Id=Guid.NewGuid(),ActorId=U(user)?.ToString()??"staff",Role=user.FindFirstValue(ClaimTypes.Role)??"",Action="REFUND_CREATED",Entity="Payment",EntityId=payment.Id.ToString()});await db.SaveChangesAsync();return Results.Accepted($"/api/admin/refunds/{refund.Id}",refund);}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.Finance));app.MapGet("/api/orders",async(DadoDbContext db)=>await db.Orders.OrderByDescending(x=>x.CreatedAt).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager,Roles.Finance,Roles.Support));app.MapGet("/api/customers",async(DadoDbContext db)=>await db.Customers.ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager,Roles.Support));app.MapGet("/api/audit",async(DadoDbContext db)=>await db.AuditLogs.OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator));app.Run();
record CreateOrderRequest(string DeliveryMethod,string PaymentMethod,List<CreateOrderItem> Items);record CreateOrderItem(Guid ProductId,string ProductName,string Variant,int Quantity,decimal UnitPrice);record WalletPayRequest(Guid OrderId);record ProductWrite(string Name,string Category,string Description,string ImageUrl,string Sizes,string Colors,decimal Price,int Stock,bool IsActive);
